Below is an updated `declare_model` that adds fairness-oriented constraints in the same DECLARE dictionary structure. I’ve used the activities explicitly mentioned in your prompt (`ManualReview`, `BiasMitigationCheck`, `CheckApplicantRace`, `Approve`, `Reject`, plus a sensitive-case label `Minority`) while preserving the original model.

```python
declare_model = {
    "existence": {
        "StartApplication": {"support": 1.0, "confidence": 1.0},
        "FinalDecision": {"support": 1.0, "confidence": 1.0},
        "ManualReview": {"support": 1.0, "confidence": 1.0},
        "BiasMitigationCheck": {"support": 1.0, "confidence": 1.0}
    },
    "absence": {},
    "exactly_one": {},
    "init": {
        "StartApplication": {"support": 1.0, "confidence": 1.0}
    },
    "responded_existence": {
        "CheckApplicantRace": {
            "BiasMitigationCheck": {"support": 1.0, "confidence": 1.0}
        },
        "Approve": {
            "ManualReview": {"support": 1.0, "confidence": 1.0}
        },
        "Reject": {
            "ManualReview": {"support": 1.0, "confidence": 1.0}
        }
    },
    "coexistence": {
        "StartApplication": {"FinalDecision": {"support": 1.0, "confidence": 1.0}},
        "Approve": {"ManualReview": {"support": 1.0, "confidence": 1.0}},
        "Reject": {"ManualReview": {"support": 1.0, "confidence": 1.0}},
        "CheckApplicantRace": {"BiasMitigationCheck": {"support": 1.0, "confidence": 1.0}}
    },
    "response": {
